package com.petcare.backend.controller;
import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.*;
import com.petcare.backend.dto.common.PageResponse;import com.petcare.backend.dto.admin.pet.response.*;import com.petcare.backend.dto.vaccination.response.VaccinationResponse;import com.petcare.backend.model.Pet;import com.petcare.backend.service.AdminPetService;import java.util.List;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;
@ExtendWith(MockitoExtension.class) class AdminPetControllerTest {@Mock AdminPetService service;AdminPetController controller;@BeforeEach void init(){controller=new AdminPetController(service);}@Test void allMethodsDelegate(){var page=PageResponse.<AdminPetResponse>builder().content(List.of()).build();when(service.getPets(null,null,null,null,null,0,20)).thenReturn(page);assertThat(controller.getPets(null,null,null,null,null,0,20).getBody().getData()).isSameAs(page);AdminPetDetailResponse detail=mock(AdminPetDetailResponse.class);when(service.getPetDetail(1L)).thenReturn(detail);assertThat(controller.getPetDetail(1L).getBody().getData()).isSameAs(detail);List<VaccinationResponse> list=List.of();when(service.getPetVaccinations(1L,null)).thenReturn(list);assertThat(controller.getPetVaccinations(1L,null).getBody().getData()).isSameAs(list);}}
